 * Anchored to Postgres's own sentence templates, not to a bare quoted word.
 *
 * `relation "..."` on its own appears inside row data too — an `invalid input
 * syntax` error quotes the offending value in its primary message, where no
 * detail marker precedes it. Requiring the surrounding words means a value has
 * to reproduce a whole Postgres sentence to be mistaken for a schema name.
 */
const RELATION_PATTERNS = [
    /relation \\?"([A-Za-z0-9_]+)\\?" violates/,
    /\bof relation \\?"([A-Za-z0-9_]+)\\?"/,
    /on table \\?"([A-Za-z0-9_]+)\\?" violates/,
];
const CONSTRAINT_PATTERNS = [
    /violates (?:check|unique|foreign key|not-null|exclusion) constraint \\?"([A-Za-z0-9_]+)\\?"/,
