const nextJest = require('next/jest')

// Provide the path to your Next.js app to load next.config.js and .env files in your test environment
const createJestConfig = nextJest({
  dir: './',
})

// Shared by both projects; only the file selection differs.
const baseConfig = {
  setupFilesAfterEnv: ['<rootDir>/jest.setup.js'],
  testEnvironment: 'jest-environment-jsdom',
  moduleNameMapper: {
    '^@/(.*)$': '<rootDir>/$1',
  },
  testPathIgnorePatterns: ['<rootDir>/.next/', '<rootDir>/node_modules/', '<rootDir>/e2e/'],
}

/**
 * Two projects, because the database tests share one Postgres and must not run
 * beside each other.
 *
 * They assert against whole tables on purpose — `seatAssignmentCoverage` proves
 * the invariant #137 relied on holds for data it did not create — so a fixture
 * another file is holding open gets counted, and the run fails on work that is
 * not its own (#155). Running them one file at a time removes the overlap
 * without weakening a single assertion.
 *
 * It is close to free: those 9 files take 9.4s serially against 9.0s in
 * parallel, since they wait on the database rather than the CPU.
 */
const DATABASE_TESTS = '\\.database\\.test\\.ts$'

module.exports = async () => ({
  projects: [
    await createJestConfig({
      ...baseConfig,
      displayName: 'unit',
      testPathIgnorePatterns: [...baseConfig.testPathIgnorePatterns, DATABASE_TESTS],
    })(),
    await createJestConfig({
      ...baseConfig,
      displayName: 'database',
      testMatch: ['**/*.database.test.ts'],
    })(),
  ],
})

const nextJest = require('next/jest')

const createJestConfig = nextJest({
  // Provide the path to your Next.js app to load next.config.js and .env files in your test environment
  dir: './',
})

// Add any custom config to be passed to Jest. Shared by both projects below;
// only the file selection differs.
const customJestConfig = {
  setupFilesAfterEnv: ['<rootDir>/jest.setup.js'],
  testEnvironment: 'jest-environment-jsdom',
  moduleNameMapper: {
    '^@/(.*)$': '<rootDir>/$1',
  },
  testPathIgnorePatterns: ['<rootDir>/.next/', '<rootDir>/node_modules/', '<rootDir>/e2e/'],
}

const DATABASE_TESTS = '\\.database\\.test\\.ts$'

/**
 * Two projects, because the database tests share one Postgres and must not run
 * beside each other.
 *
 * Several assert against whole tables on purpose — `seatAssignmentCoverage`
 * proves the invariant #137 relied on holds for data the test did not create —
 * so a fixture another file is holding open gets counted and the run fails on
 * work that is not its own (#155). Running them one file at a time removes the
 * overlap without weakening a single assertion.
 *
 * `npm run test:database` passes `--runInBand`, which is what actually
 * serialises them; splitting the projects is what lets it apply to those files
 * alone. It costs almost nothing — those 9 files take 9.4s serially against
 * 9.0s in parallel, because they wait on the database rather than the CPU.
 *
 * createJestConfig is called this way to ensure next/jest can load the Next.js
 * config, which is async.
 */
module.exports = async () => ({
  projects: [
    await createJestConfig({
      ...customJestConfig,
      displayName: 'unit',
      testPathIgnorePatterns: [...customJestConfig.testPathIgnorePatterns, DATABASE_TESTS],
    })(),
    await createJestConfig({
      ...customJestConfig,
      displayName: 'database',
      testMatch: ['**/*.database.test.ts'],
    })(),
  ],
})

